import{_ as e,o as n,c as o,a5 as i}from"./chunks/framework.CsGesDJn.js";const u=JSON.parse('{"title":"Test Specification — FR 3.10.4: Content Moderation Queue","description":"","frontmatter":{},"headers":[],"relativePath":"feature/admin-management/3-10-4-content-moderation-queue/test.md","filePath":"feature/admin-management/3-10-4-content-moderation-queue/test.md"}'),d={name:"feature/admin-management/3-10-4-content-moderation-queue/test.md"};function s(a,t,c,l,r,g){return n(),o("div",null,[...t[0]||(t[0]=[i(`<h1 id="test-specification-—-fr-3-10-4-content-moderation-queue" tabindex="-1">Test Specification — FR 3.10.4: Content Moderation Queue <a class="header-anchor" href="#test-specification-—-fr-3-10-4-content-moderation-queue" aria-label="Permalink to &quot;Test Specification — FR 3.10.4: Content Moderation Queue&quot;">​</a></h1><h2 id="_1-traceability-execution-summary" tabindex="-1">1. Traceability &amp; Execution Summary <a class="header-anchor" href="#_1-traceability-execution-summary" aria-label="Permalink to &quot;1. Traceability &amp; Execution Summary&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Field</th><th style="text-align:left;">Value</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>FR ID</strong></td><td style="text-align:left;"><code>FR 3.10.4</code></td></tr><tr><td style="text-align:left;"><strong>Function Name</strong></td><td style="text-align:left;">Content Moderation Queue</td></tr><tr><td style="text-align:left;"><strong>Functional Domain</strong></td><td style="text-align:left;">Admin</td></tr><tr><td style="text-align:left;"><strong>Canonical Actors / Roles</strong></td><td style="text-align:left;"><code>Admin</code></td></tr><tr><td style="text-align:left;"><strong>Target Class &amp; Method</strong></td><td style="text-align:left;"><code>ContentModerationService.decide()</code> (49 LOC)</td></tr><tr><td style="text-align:left;"><strong>Unit Test File</strong></td><td style="text-align:left;"><code>brandhub-business-service/src/test/java/com/brandhub/business/service/admin/ContentModerationServiceTest.java</code></td></tr><tr><td style="text-align:left;"><strong>Code &amp; Test Author</strong></td><td style="text-align:left;">Ân</td></tr><tr><td style="text-align:left;"><strong>Test Requirement</strong></td><td style="text-align:left;">Allow Admin to approve (note &gt;= 10 chars) or block (recording strike + returning post to DRAFT) a pending moderation item</td></tr><tr><td style="text-align:left;"><strong>Preconditions</strong></td><td style="text-align:left;">Can connect with server; Caller has ADMIN system role</td></tr><tr><td style="text-align:left;"><strong>Overall Status</strong></td><td style="text-align:left;"><strong>Passed (100%)</strong></td></tr><tr><td style="text-align:left;"><strong>Test Case Breakdown</strong></td><td style="text-align:left;"><strong>Total: 16</strong> (<code>Passed</code>: 16, <code>Failed</code>: 0, <code>Untested</code>: 0) — <code>Normal (N)</code>: 8, <code>Boundary (B)</code>: 3, <code>Abnormal (A)</code>: 5</td></tr></tbody></table><hr><h2 id="_2-unit-test-case-matrix-utcid01–utcid16" tabindex="-1">2. Unit Test Case Matrix (<code>UTCID01</code>–<code>UTCID16</code>) <a class="header-anchor" href="#_2-unit-test-case-matrix-utcid01–utcid16" aria-label="Permalink to &quot;2. Unit Test Case Matrix (\`UTCID01\`–\`UTCID16\`)&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Test Case ID</th><th style="text-align:center;">Type</th><th style="text-align:left;">Preconditions</th><th style="text-align:left;">Test Inputs</th><th style="text-align:left;">Expected Return / Exception</th><th style="text-align:left;">Log Message</th><th style="text-align:center;">Status</th></tr></thead><tbody><tr><td style="text-align:left;"><code>UTCID01</code></td><td style="text-align:center;"><code>N</code></td><td style="text-align:left;">Can connect with server; Caller has ADMIN system role (AdminAccountService.requireAdmin); Moderation review item exists in PENDING status matching PostDocument.contentVersion</td><td style="text-align:left;"><code>id</code> = <code>PENDING review UUID (COMPLIANCE)</code>, <code>request</code> = <code>Decision.APPROVE, note=&#39;Verified safe content&#39;</code></td><td style="text-align:left;">200 OK - Decision.APPROVE sets review status=&#39;APPROVED&#39;, increments row_version, notifies author</td><td style="text-align:left;">—</td><td style="text-align:center;"><strong>Passed</strong></td></tr><tr><td style="text-align:left;"><code>UTCID02</code></td><td style="text-align:center;"><code>N</code></td><td style="text-align:left;">Can connect with server; Caller has ADMIN system role (AdminAccountService.requireAdmin); Moderation review item exists in PENDING status matching PostDocument.contentVersion</td><td style="text-align:left;"><code>id</code> = <code>PENDING review UUID (COMPLIANCE)</code>, <code>request</code> = <code>Decision.BLOCK, strikeLevel=YELLOW, category=&#39;CONTENT_POLICY&#39;, note=&#39;Profanity&#39;</code></td><td style="text-align:left;">200 OK - Decision.BLOCK sets status=&#39;BLOCKED&#39;, records strike via AdminAccountService.record</td><td style="text-align:left;">—</td><td style="text-align:center;"><strong>Passed</strong></td></tr><tr><td style="text-align:left;"><code>UTCID03</code></td><td style="text-align:center;"><code>N</code></td><td style="text-align:left;">Can connect with server; Caller has ADMIN system role (AdminAccountService.requireAdmin); Moderation review item exists in PENDING status matching PostDocument.contentVersion</td><td style="text-align:left;"><code>id</code> = <code>PENDING review UUID (FLAGGED_AUTHOR)</code>, <code>request</code> = <code>Decision.APPROVE, note=&#39;Verified safe content&#39;</code></td><td style="text-align:left;">200 OK - Decision.BLOCK returns PENDING_APPROVAL post in Mongo back to DRAFT for editing</td><td style="text-align:left;">—</td><td style="text-align:center;"><strong>Passed</strong></td></tr><tr><td style="text-align:left;"><code>UTCID04</code></td><td style="text-align:center;"><code>N</code></td><td style="text-align:left;">Can connect with server; Caller has ADMIN system role (AdminAccountService.requireAdmin); Moderation review item exists in PENDING status matching PostDocument.contentVersion</td><td style="text-align:left;"><code>id</code> = <code>PENDING review UUID (FLAGGED_AUTHOR)</code>, <code>request</code> = <code>Decision.BLOCK, strikeLevel=YELLOW, category=&#39;CONTENT_POLICY&#39;, note=&#39;Profanity&#39;</code></td><td style="text-align:left;">200 OK - list() returns AdminModerationItem.Page with pending and today reviewed counts</td><td style="text-align:left;">—</td><td style="text-align:center;"><strong>Passed</strong></td></tr><tr><td style="text-align:left;"><code>UTCID05</code></td><td style="text-align:center;"><code>N</code></td><td style="text-align:left;">Can connect with server; Caller has ADMIN system role (AdminAccountService.requireAdmin); Immutable snapshot of reviewed version is stored in Mongo post_versions collection</td><td style="text-align:left;"><code>id</code> = <code>PENDING review UUID (COMPLIANCE)</code>, <code>request</code> = <code>list(status=&#39;PENDING&#39;, source=&#39;COMPLIANCE&#39;, page=1, size=20)</code></td><td style="text-align:left;">200 OK - detail() returns AdminModerationItem with immutable Mongo post_versions snapshot</td><td style="text-align:left;">—</td><td style="text-align:center;"><strong>Passed</strong></td></tr><tr><td style="text-align:left;"><code>UTCID06</code></td><td style="text-align:center;"><code>N</code></td><td style="text-align:left;">Can connect with server; Caller has ADMIN system role (AdminAccountService.requireAdmin); Immutable snapshot of reviewed version is stored in Mongo post_versions collection</td><td style="text-align:left;"><code>id</code> = <code>PENDING review UUID (FLAGGED_AUTHOR)</code>, <code>request</code> = <code>list(status=&#39;PENDING&#39;, source=&#39;COMPLIANCE&#39;, page=1, size=20)</code></td><td style="text-align:left;">200 OK - eligibility() returns ALLOWED/APPROVED or holds FLAGGED author&#39;s unreviewed post</td><td style="text-align:left;">—</td><td style="text-align:center;"><strong>Passed</strong></td></tr><tr><td style="text-align:left;"><code>UTCID07</code></td><td style="text-align:center;"><code>N</code></td><td style="text-align:left;">Can connect with server; Caller has ADMIN system role (AdminAccountService.requireAdmin); Moderation review item exists in PENDING status matching PostDocument.contentVersion</td><td style="text-align:left;"><code>id</code> = <code>PENDING review UUID (COMPLIANCE)</code>, <code>request</code> = <code>Decision.APPROVE, note=&#39;Verified safe content&#39;</code></td><td style="text-align:left;">200 OK - AdminAudit records CONTENT_MODERATION UPDATE and AdminEmailOutbox queues author email</td><td style="text-align:left;">—</td><td style="text-align:center;"><strong>Passed</strong></td></tr><tr><td style="text-align:left;"><code>UTCID08</code></td><td style="text-align:center;"><code>N</code></td><td style="text-align:left;">Can connect with server; Caller has ADMIN system role (AdminAccountService.requireAdmin); Moderation review item exists in PENDING status matching PostDocument.contentVersion</td><td style="text-align:left;"><code>id</code> = <code>PENDING review UUID (COMPLIANCE)</code>, <code>request</code> = <code>Decision.BLOCK, strikeLevel=YELLOW, category=&#39;CONTENT_POLICY&#39;, note=&#39;Profanity&#39;</code></td><td style="text-align:left;">200 OK - flag() reuses existing review item idempotently on duplicate (postId, contentVersion)</td><td style="text-align:left;">—</td><td style="text-align:center;"><strong>Passed</strong></td></tr><tr><td style="text-align:left;"><code>UTCID09</code></td><td style="text-align:center;"><code>B</code></td><td style="text-align:left;">Can connect with server; Caller has ADMIN system role (AdminAccountService.requireAdmin); Decision note is at exact minimum length boundary (10 chars for APPROVE, 3 chars for BLOCK)</td><td style="text-align:left;"><code>id</code> = <code>PENDING review UUID (boundary note)</code>, <code>request</code> = <code>APPROVE with exact 10-char note / BLOCK with 3-char note</code></td><td style="text-align:left;">200 OK - APPROVE with exact 10-character note accepted at minimum boundary</td><td style="text-align:left;">—</td><td style="text-align:center;"><strong>Passed</strong></td></tr><tr><td style="text-align:left;"><code>UTCID10</code></td><td style="text-align:center;"><code>B</code></td><td style="text-align:left;">Can connect with server; Caller has ADMIN system role (AdminAccountService.requireAdmin); Decision note is at exact minimum length boundary (10 chars for APPROVE, 3 chars for BLOCK)</td><td style="text-align:left;"><code>id</code> = <code>PENDING review UUID (boundary note)</code>, <code>request</code> = <code>APPROVE with exact 10-char note / BLOCK with 3-char note</code></td><td style="text-align:left;">200 OK - BLOCK with exact 3-character note and default category=&#39;CONTENT_POLICY&#39; accepted</td><td style="text-align:left;">—</td><td style="text-align:center;"><strong>Passed</strong></td></tr><tr><td style="text-align:left;"><code>UTCID11</code></td><td style="text-align:center;"><code>B</code></td><td style="text-align:left;">Can connect with server; Caller has ADMIN system role (AdminAccountService.requireAdmin); Moderation review item exists in PENDING status matching PostDocument.contentVersion</td><td style="text-align:left;"><code>id</code> = <code>PENDING review UUID (COMPLIANCE)</code>, <code>request</code> = <code>list(status=&#39;PENDING&#39;, source=&#39;COMPLIANCE&#39;, page=1, size=20)</code></td><td style="text-align:left;">200 OK - Operation ID = review ID prevents duplicate strike on retried BLOCK</td><td style="text-align:left;">—</td><td style="text-align:center;"><strong>Passed</strong></td></tr><tr><td style="text-align:left;"><code>UTCID12</code></td><td style="text-align:center;"><code>A</code></td><td style="text-align:left;">Can connect with server; Caller has ADMIN system role (AdminAccountService.requireAdmin); Review item is not found, already decided, rowVersion mismatches, or post version changed</td><td style="text-align:left;"><code>id</code> = <code>non-existent review UUID</code>, <code>request</code> = <code>Decision.APPROVE, note=&#39;Verified safe content&#39;</code></td><td style="text-align:left;">MODERATION_NOT_FOUND - 404 Moderation review ID or flagged post not found</td><td style="text-align:left;">—</td><td style="text-align:center;"><strong>Passed</strong></td></tr><tr><td style="text-align:left;"><code>UTCID13</code></td><td style="text-align:center;"><code>A</code></td><td style="text-align:left;">Can connect with server; Caller has ADMIN system role (AdminAccountService.requireAdmin); Review item is not found, already decided, rowVersion mismatches, or post version changed</td><td style="text-align:left;"><code>id</code> = <code>already decided or stale-version UUID</code>, <code>request</code> = <code>Decision.APPROVE, note=&#39;Verified safe content&#39;</code></td><td style="text-align:left;">ADMIN_STATE_CONFLICT - 409 Review is no longer PENDING, rowVersion stale, or post version changed</td><td style="text-align:left;">—</td><td style="text-align:center;"><strong>Passed</strong></td></tr><tr><td style="text-align:left;"><code>UTCID14</code></td><td style="text-align:center;"><code>A</code></td><td style="text-align:left;">Can connect with server; Caller does not have ADMIN system role</td><td style="text-align:left;"><code>id</code> = <code>PENDING review UUID (COMPLIANCE)</code>, <code>request</code> = <code>Decision.APPROVE, note=&#39;Verified safe content&#39;</code></td><td style="text-align:left;">FORBIDDEN - 403 Caller does not have ADMIN system role</td><td style="text-align:left;">—</td><td style="text-align:center;"><strong>Passed</strong></td></tr><tr><td style="text-align:left;"><code>UTCID15</code></td><td style="text-align:center;"><code>A</code></td><td style="text-align:left;">Can connect with server; Caller has ADMIN system role (AdminAccountService.requireAdmin); Moderation review item exists in PENDING status matching PostDocument.contentVersion</td><td style="text-align:left;"><code>id</code> = <code>non-existent review UUID</code>, <code>request</code> = <code>APPROVE with &lt;10-char note</code></td><td style="text-align:left;">MODERATION_NOTE_TOO_SHORT - 400 APPROVE decision note must be at least 10 characters</td><td style="text-align:left;">—</td><td style="text-align:center;"><strong>Passed</strong></td></tr><tr><td style="text-align:left;"><code>UTCID16</code></td><td style="text-align:center;"><code>A</code></td><td style="text-align:left;">Can connect with server; Caller has ADMIN system role (AdminAccountService.requireAdmin); Moderation review item exists in PENDING status matching PostDocument.contentVersion</td><td style="text-align:left;"><code>id</code> = <code>already decided or stale-version UUID</code>, <code>request</code> = <code>BLOCK without strikeLevel or &lt;3-char note</code></td><td style="text-align:left;">VALIDATION_ERROR - 400 BLOCK decision requires strikeLevel and note &gt;= 3 characters</td><td style="text-align:left;">—</td><td style="text-align:center;"><strong>Passed</strong></td></tr></tbody></table><hr><h2 id="_3-synchronization-verification-notes" tabindex="-1">3. Synchronization &amp; Verification Notes <a class="header-anchor" href="#_3-synchronization-verification-notes" aria-label="Permalink to &quot;3. Synchronization &amp; Verification Notes&quot;">​</a></h2><ul><li>Synchronized 1-to-1 with <a href="./../../../../brandhub-final_report/report5/Report5_Unit Test.xls.html"><code>Report5_Unit Test.xls</code></a> sheet <code>FR3.10.4</code>, <a href="./../../../../brandhub-final_report/report5/Report5_Test Report.xlsx.html"><code>Report5_Test Report.xlsx</code></a>, and <a href="./../../../../brandhub-final_report/report5/Report5_Test Documentation.docx.html"><code>Report5_Test Documentation.docx</code></a>.</li><li>Role names strictly follow the 6 canonical roles (<code>Guest</code>, <code>Owner</code>, <code>Manager</code>, <code>Creator</code>, <code>Client</code>, <code>Admin</code>).</li></ul><hr><h2 id="_4-feature-acceptance-integration-verification" tabindex="-1">4. Feature Acceptance &amp; Integration Verification <a class="header-anchor" href="#_4-feature-acceptance-integration-verification" aria-label="Permalink to &quot;4. Feature Acceptance &amp; Integration Verification&quot;">​</a></h2><h1 id="test-—-3-10-4-content-moderation-queue" tabindex="-1">Test — 3-10-4-content-moderation-queue <a class="header-anchor" href="#test-—-3-10-4-content-moderation-queue" aria-label="Permalink to &quot;Test — 3-10-4-content-moderation-queue&quot;">​</a></h1><p>Các kỳ vọng chi tiết: <a href="./spec.html">spec</a>, <a href="./report3_spec.html">Report3 spec</a> và mục 3 của <a href="./../plan.html">plan kỹ thuật</a>.</p><ul><li>[x] BR-64 phiên bản bất biến: snapshot Mongo <code>post_versions</code> khóa theo <code>postId:version</code>, PostgreSQL lưu SHA-256 trùng khớp; sửa bài tăng <code>content_version</code>.</li><li>[x] FLAGGED gửi duyệt → vào hàng đợi đúng một lần; tác giả ACTIVE không vào.</li><li>[x] Bài đã lên lịch của tác giả bị FLAGGED: <code>/eligibility</code> giữ lại (PENDING_REVIEW) và tạo mục chờ.</li><li>[x] APPROVE ghi chú &lt; 10 ký tự → MSG80; APPROVE không tự đăng, chỉ cho phép phiên bản đó.</li><li>[x] BLOCK: ghi đúng 1 thẻ (operationId = id mục), bài về DRAFT, email tác giả, <code>/eligibility</code> trả BLOCKED; sửa → phiên bản mới vào hàng đợi riêng.</li><li>[x] Quyết định trên phiên bản đã đổi, mục đã xử lý hoặc rowVersion cũ → 409; cờ nội bộ cho phiên bản cũ → 409.</li><li>[x] DEACTIVATED → AUTHOR_RESTRICTED; sai phiên bản → VERSION_MISMATCH; bài không tồn tại → POST_NOT_FOUND.</li><li>[x] Chưa đăng nhập 401; USER 403; endpoint nội bộ không có/sai khóa → 401.</li><li>[x] VI/EN và light/dark; 390px không tràn ngang.</li></ul><h2 id="ket-qua" tabindex="-1">Kết quả <a class="header-anchor" href="#ket-qua" aria-label="Permalink to &quot;Kết quả&quot;">​</a></h2><ul><li><code>ContentModerationDatabaseTest</code> 5/5 (PostgreSQL 17 test DB + Mongo local DB <code>brandhub_moderation_test</code>); <code>AdminSecurityTest</code> 13/13; <code>PostServiceImplTest</code> pass sau khi thêm mock và test phiên bản.</li><li>Full Business suite: 381 test, 0 failure, 11 error baseline (WorkspaceController/WorkspaceTemplate thiếu mock <code>RequireRoleAspect</code>, có từ upstream).</li><li>Playwright <code>tests/e2e/admin/*</code> 33/33 pass (gồm <code>moderation.spec.ts</code> 4/4). 6 test <code>tests/e2e/auth/{login,register,google-oauth}</code> lỗi giống hệt trên <code>develop</code> gốc (UI đã đổi sau khi viết test), không do thay đổi này.</li><li>Smoke thật: 18 bài demo Mongo local; giả lập publisher gọi <code>/eligibility</code> → 12 bài của tác giả FLAGGED bị giữ; giả lập kiểm tra tự động gọi <code>/flags</code> → 3 mục; duyệt 1, chặn 1 (thẻ Cam) qua UI; 2 email, audit đủ.</li></ul><h2 id="hop-đong-tich-hop" tabindex="-1">Hợp đồng tích hợp <a class="header-anchor" href="#hop-đong-tich-hop" aria-label="Permalink to &quot;Hợp đồng tích hợp&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>POST /api/v1/internal/moderation/flags            (Tuấn — FR 3.6.33/3.6.34)</span></span>
<span class="line"><span>Header X-Internal-Service-Key: \${INTERNAL_SERVICE_KEY}</span></span>
<span class="line"><span>{ &quot;postId&quot;: &quot;...&quot;, &quot;contentVersion&quot;: 3, &quot;source&quot;: &quot;COMPLIANCE|COPYRIGHT&quot;, &quot;reason&quot;: &quot;...&quot; }</span></span>
<span class="line"><span>→ 200 { &quot;data&quot;: { &quot;moderationId&quot;: &quot;...&quot; } }   409 nếu contentVersion không còn là bản hiện tại</span></span>
<span class="line"><span></span></span>
<span class="line"><span>POST /api/v1/internal/moderation/eligibility?postId=...&amp;contentVersion=3   (Phước — trước dispatch)</span></span>
<span class="line"><span>→ 200 { &quot;data&quot;: { &quot;allowed&quot;: false, &quot;code&quot;: &quot;PENDING_REVIEW|BLOCKED|VERSION_MISMATCH|AUTHOR_RESTRICTED|POST_NOT_FOUND|APPROVED|ALLOWED&quot;, &quot;reviewId&quot;: &quot;...&quot; } }</span></span>
<span class="line"><span>Chỉ đăng khi allowed=true; lỗi mạng/không xác minh được → không đăng (fail closed).</span></span></code></pre></div><p>Giới hạn: hàng đợi chỉ có dữ liệu thật khi Tuấn/Phước nối hai endpoint; <code>PublishJobMessage</code> hiện chưa mang <code>contentVersion</code> nên Phước cần bổ sung.</p><h2 id="local-schema-recovery-—-2026-10-14" tabindex="-1">Local schema recovery — 2026-10-14 <a class="header-anchor" href="#local-schema-recovery-—-2026-10-14" aria-label="Permalink to &quot;Local schema recovery — 2026-10-14&quot;">​</a></h2><p>Kịch bản trước khi thực hiện:</p><ul><li>Backup đọc được trước khi áp dụng SQL; đúng DB <code>brandhub</code>, schema <code>public</code>.</li><li>Migration lần đầu và chạy lại thành công, không xóa/sửa dữ liệu cũ.</li><li>Đủ bảng, khóa chính, unique post/version, foreign keys, CHECK và hai index queue/author.</li><li>Query danh sách PENDING/APPROVED/BLOCKED và bộ đếm thực thi thành công, trả rỗng/0 trên bảng mới.</li><li>Định nghĩa bảng trong init khớp migration hiện có, không cần bổ sung lần nữa.</li><li>AdminSecurityTest giữ nguyên kiểm tra 401/403/quyền Admin. Không coi test controller mock là live authenticated smoke.</li></ul><p>Kết quả thực tế:</p><ul><li>Backup full PostgreSQL custom-format, kiểm tra <code>pg_restore --list</code> thành công. File ngoài Git: <code>D:/FPT/FA26/SEP490/.local-backups/admin-moderation-20261014/brandhub-before-moderation.dump</code> (552852 bytes).</li><li>Chạy migration hiện có trên <code>brandhub/public</code> thành công, chạy lại thành công. Có 11 constraints và 4 indexes tổng cộng (2 index tường minh cùng index PK/unique).</li><li>Trích đúng SQL SELECT của ContentModerationService và thực thi read-only với cả PENDING/APPROVED/BLOCKED: thành công, mỗi trạng thái 0 dòng; tổng/pending/today đều 0. Không seed hoặc tạo quyết định giả.</li><li>Định nghĩa bảng/index/comment trong init khớp chính xác migration sau chuẩn hóa CRLF, không sửa init hoặc migration cũ.</li><li><code>mvn.cmd -q -Dtest=AdminSecurityTest test</code>: 15 tests, 0 failures/errors/skips. Controller/security dùng mocks; không coi đây là smoke API có phiên Admin thật.</li><li>Chỉ cần tải lại <code>/admin?view=moderation</code> hoặc bấm tải lại danh sách. Không cần restart vì chỉ bổ sung schema vào PostgreSQL hiện đang dùng.</li><li>Không thay đổi code Web/Business/Gateway, Mongo, Dashboard hoặc logout trong lần sửa riêng này. Giữ nguyên các thay đổi local từ công việc trước; không commit/push. Chưa xác minh thao tác duyệt/chặn trên dữ liệu thật hoặc Mongo Atlas.</li></ul>`,24)])])}const m=e(d,[["render",s]]);export{u as __pageData,m as default};
